body {
  background-color: #f5f6f8;
  color: #18181b;
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
  padding: 16px;
}

h1 { font-size: 32px; }
h2 { font-size: 20px; }

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.cart-count {
  background-color: #2563eb;
  color: #ffffff;
  border-radius: 999px;
  padding: 2px 10px;
}

.product-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

@media (min-width: 768px) {
  .product-grid { grid-template-columns: 1fr 1fr 1fr; }
}

.product-card {
  background-color: #ffffff;
  padding: 16px;
  border-radius: 10px;
}

.btn-add {
  background-color: #2563eb;
  color: #ffffff;
  padding: 10px 16px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  font-size: 15px;
}

.btn-add:disabled,
.btn-refresh:disabled {
  background-color: #e4e4e7;
  color: #71717a;
  cursor: not-allowed;
}

.btn-refresh {
  margin-left: auto;
  margin-right: 12px;
  background-color: #ffffff;
  color: #1d4ed8;
  border: 1px solid #bfdbfe;
  border-radius: 6px;
  padding: 6px 12px;
  cursor: pointer;
  font-size: 14px;
}

.cart {
  background-color: #ffffff;
  padding: 16px;
  border-radius: 10px;
  margin-top: 24px;
}

.cart-total {
  font-size: 20px;
  font-weight: 700;
  text-align: right;
}

.error {
  background-color: #fef2f2;
  border: 1px solid #fecaca;
  border-radius: 10px;
  padding: 16px;
  color: #991b1b;
}

.muted {
  color: #52525b;
  font-size: 14px;
}

.ok {
  background-color: #ecfdf5;
  border: 1px solid #a7f3d0;
  border-radius: 10px;
  padding: 16px;
  color: #065f46;
}

// Жижиг «дуураймал сервер». Сүлжээ хэрэггүй — window.fetch-ийг орлуулна.
// Дараагийн шатанд үүнийг ЖИНХЭНЭ сервер солино; таны бичсэн код өөрчлөгдөхгүй.

(function () {
  const products = [
    { id: 1, name: "Монгол дээл", price: 129000, stock: 4 },
    { id: 2, name: "Малгай", price: 45000, stock: 12 },
    { id: 3, name: "Гутал", price: 89000, stock: 0 },
    { id: 4, name: "Дээлний бүс", price: 25000, stock: 7 },
    { id: 5, name: "Ноосон оймс", price: 12000, stock: 20 },
  ];

  const orders = [];
  const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

  function json(body, status) {
    return new Response(JSON.stringify(body), {
      status: status || 200,
      headers: { "Content-Type": "application/json" },
    });
  }

  window.fetch = async function (url, options) {
    const method = ((options && options.method) || "GET").toUpperCase();
    await wait(60);

    // Алдааны төлөвөө турших унтраалга: console-д window.API_SHOULD_FAIL = true
    if (window.API_SHOULD_FAIL) {
      return json({ error: "Серверт алдаа гарлаа" }, 500);
    }

    // Бараа: ?q= хайлтын үгээр нэрээр нь шүүнэ
    if (method === "GET" && String(url).split("?")[0].endsWith("/api/products")) {
      const params = new URLSearchParams(String(url).split("?")[1] || "");
      const q = (params.get("q") || "").trim().toLowerCase();
      let list = window.API_EMPTY ? [] : products;
      if (q) {
        list = list.filter((p) => p.name.toLowerCase().includes(q));
      }
      return json(list);
    }

    if (String(url).endsWith("/api/orders") && method === "GET") {
      return json(orders);
    }

    if (String(url).endsWith("/api/orders") && method === "POST") {
      const order = JSON.parse(options.body);
      if (!order.items || order.items.length === 0) {
        return json({ error: "Сагс хоосон байна" }, 400);
      }
      const saved = { id: orders.length + 1, ...order };
      orders.push(saved);
      return json(saved, 201);
    }

    return json({ error: "Хаяг олдсонгүй" }, 404);
  };
})();

import React, { useState, useEffect } from "react";
import { createRoot } from "react-dom/client";

function formatPrice(value) {
  return "₮ " + value.toLocaleString("en-US");
}

function useCart() {
  const [cart, setCart] = useState([]);

  function addToCart(product) {
    setCart((prev) => {
      const existing = prev.find((item) => item.id === product.id);
      if (existing) {
        return prev.map((item) =>
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { id: product.id, name: product.name, price: product.price, quantity: 1 }];
    });
  }

  const count = cart.reduce((sum, item) => sum + item.quantity, 0);
  const totalPrice = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);

  return { cart, addToCart, count, totalPrice };
}

function ProductCard({ product, onAdd }) {
  return (
    <article className="product-card">
      <h3>{product.name}</h3>
      <p className="price">{formatPrice(product.price)}</p>
      <button
        className="btn-add"
        data-testid="add-to-cart"
        onClick={() => onAdd(product)}
        disabled={product.stock === 0}
      >
        {product.stock === 0 ? "Дууссан" : "Сагсанд хийх"}
      </button>
    </article>
  );
}

function App() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [query, setQuery] = useState("");
  const { cart, addToCart, count, totalPrice } = useCart();
  const ready = !loading && !error;

  async function loadProducts(search) {
    setError(null);
    setLoading(true);

    try {
      // энд бичнэ үү — "/api/products" хаягт ?q=search гэсэн query нэмнэ үү
      const response = await fetch("/api/products");
      setProducts(await response.json());
    } catch (problem) {
      setError(problem.message);
    } finally {
      setLoading(false);
    }
  }

  function handleSearch(value) {
    setQuery(value);
    loadProducts(value);
  }

  useEffect(() => {
    loadProducts("");
  }, []);

  return (
    <main>
      <header className="topbar">
        <h1>Shop.mn</h1>
        <span className="cart-count" data-testid="cart-count">{count}</span>
      </header>

      <input
        className="btn-refresh"
        data-testid="search"
        type="search"
        placeholder="Бараа хайх…"
        value={query}
        onChange={(e) => handleSearch(e.target.value)}
      />

      {loading ? <p data-testid="loading">Ачаалж байна…</p> : null}

      {/* энд бичнэ үү — ready бөгөөд илэрц хоосон бол "Илэрц олдсонгүй" мессеж */}

      {ready ? (
        <section className="product-grid" data-testid="grid">
          {products.map((product) => (
            <ProductCard key={product.id} product={product} onAdd={addToCart} />
          ))}
        </section>
      ) : null}

      <section className="cart">
        <h2>Сагс</h2>
        <p className="cart-total" data-testid="cart-total">{formatPrice(totalPrice)}</p>
      </section>
    </main>
  );
}

createRoot(document.getElementById("root")).render(<App />);

